-- Immutable version-one collection. No application data is modified.
create table mv_private.legend_catalog(id text primary key, definition jsonb not null);
create table mv_private.legend_projects(id text primary key, definition jsonb not null);

alter table mv_private.legend_catalog enable row level security;
alter table mv_private.legend_projects enable row level security;
create table public.mv_achievements (
 family_id uuid not null references public.mv_families(id),
 achievement_id text not null references mv_private.legend_catalog(id),
 owner text not null check(owner in ('family','anton','tanya')),
 xp integer not null check(xp in (10,25,50,100)),
 unlocked_at timestamptz not null default now(),
 historical boolean not null default false,
 primary key(family_id,achievement_id)
);
create table public.mv_legend_seen (
 user_id uuid primary key references auth.users(id),
 initialized_at timestamptz not null default now(),
 seen_ids text[] not null default '{}'
);
alter table public.mv_achievements enable row level security;
alter table public.mv_legend_seen enable row level security;
create policy family_read on public.mv_achievements for select to authenticated using (family_id=mv_private.family());
create policy own_read on public.mv_legend_seen for select to authenticated using(user_id=auth.uid());
grant select on public.mv_achievements,public.mv_legend_seen to authenticated;
revoke insert,update,delete on public.mv_achievements,public.mv_legend_seen from anon,authenticated;

create function mv_private.legend_complete(f uuid,p text) returns boolean language sql stable security definer set search_path='' as $$
 select coalesce((select case when d->>'section'='future' or (d->>'date')::date>current_date then false
 when d->>'type'<>'series' then exists(select 1 from public.mv_entries e where e.family_id=f and e.project_id=p and e.watched)
 else jsonb_array_length(d->'seasons')>0 and not exists(
 select 1 from jsonb_array_elements(d->'seasons') s cross join lateral generate_series(1,(s->>'episodes')::int) ep
 where coalesce((s->'episodeDates'->>(ep-1))::date,(s->>'date')::date)>current_date
 or not exists(select 1 from public.mv_episodes e where e.family_id=f and e.project_id=p and e.season=(s->>'number')::int and e.episode=ep and e.watched)) end
 from (select definition d from mv_private.legend_projects where id=p) t),false)
$$;

create function mv_private.legend_refresh(f uuid, historical boolean default false) returns void language plpgsql security definer set search_path='' as $$
declare a jsonb; n int; metric text; threshold int; role_name text;
begin
 perform pg_advisory_xact_lock(hashtextextended('legend:'||f::text,0));
 for a in select definition from mv_private.legend_catalog loop
 metric:=a->>'metric';threshold:=(a->>'threshold')::int;role_name:=a->>'owner';n:=0;
 if metric in ('collection','watched') then
 if jsonb_array_length(a->'projects')>0 then
 select count(*) into n from jsonb_array_elements_text(a->'projects') p where mv_private.legend_complete(f,p);
 else select count(*) into n from mv_private.legend_projects p where p.definition->>'type'='film' and p.definition->>'section'='main' and mv_private.legend_complete(f,p.id);end if;
 elsif metric='series' then
 select count(*) into n from mv_private.legend_projects p where p.definition->>'type'='series' and mv_private.legend_complete(f,p.id);
 elsif metric='episodes' then
 select count(*) into n from public.mv_episodes e join mv_private.legend_projects p on p.id=e.project_id
 cross join lateral jsonb_array_elements(p.definition->'seasons') s
 where e.family_id=f and e.watched and e.season=(s->>'number')::int and e.episode between 1 and (s->>'episodes')::int and p.definition->>'section'<>'future'
 and coalesce((s->'episodeDates'->>(e.episode-1))::date,(s->>'date')::date)<=current_date;
 elsif metric in ('ratings','rated-series','perfect','strict','any-rating') then
 select count(distinct r.project_id) into n from public.mv_ratings r join public.mv_members m on m.user_id=r.user_id and m.family_id=f join mv_private.legend_projects p on p.id=r.project_id
 where r.family_id=f and m.role=role_name and r.score is not null
 and (case metric when 'any-rating' then true when 'ratings' then p.definition->>'type'='film' when 'rated-series' then p.definition->>'type'='series' when 'perfect' then r.score=10 else r.score<=3 end);
 elsif metric in ('paired','equal','difference3','difference4','double10') then
 select count(*) into n from public.mv_ratings x join public.mv_members mx on mx.user_id=x.user_id and mx.family_id=f and mx.role='anton'
 join public.mv_ratings y on y.family_id=f and y.project_id=x.project_id and y.season=0 join public.mv_members my on my.user_id=y.user_id and my.family_id=f and my.role='tanya'
 join mv_private.legend_projects p on p.id=x.project_id
 where x.family_id=f and x.season=0 and x.score is not null and y.score is not null and p.definition->>'type'='film'
 and case metric when 'paired' then true when 'equal' then x.score=y.score when 'double10' then x.score=10 and y.score=10 when 'difference3' then abs(x.score-y.score)>=3 else abs(x.score-y.score)>=4 end;
 elsif metric='adventure' then
 select case when count(*) filter(where p.definition->>'type'='film' and p.definition->>'section'='main')>=30 and count(*) filter(where p.definition->>'type'='series')>=5 then 1 else 0 end into n from mv_private.legend_projects p where mv_private.legend_complete(f,p.id);
 else raise exception 'UNKNOWN_LEGEND_METRIC';end if;
 if n>=threshold then
 values(f,a->>'id',role_name,case a->>'rarity' when 'legendary' then 100 when 'epic' then 50 when 'rare' then 25 else 10 end,historical) on conflict do nothing;
 end if;
 end loop;
end$$;

create function public.mv_legend(p_ack text[] default '{}') returns jsonb language plpgsql security definer set search_path='' as $$
declare f uuid:=mv_private.family();u uuid:=auth.uid();initial boolean;result jsonb;
begin
 if f is null or u is null then raise exception 'FORBIDDEN' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('legend:'||f::text,0));
 initial:=not exists(select 1 from public.mv_legend_seen where user_id=u and '__baseline__'=any(seen_ids));
 if cardinality(p_ack)>1000 then raise exception 'TOO_MANY_ACKS';end if;
 perform mv_private.legend_refresh(f,not exists(select 1 from public.mv_achievements where family_id=f));
 update public.mv_legend_seen set seen_ids=array(select distinct unnest(seen_ids||p_ack)) where user_id=u;
 select jsonb_build_object('initial',initial,'awards',coalesce((select jsonb_agg(to_jsonb(a)) from public.mv_achievements a where family_id=f),'[]'::jsonb),'seen',(select to_jsonb(seen_ids) from public.mv_legend_seen where user_id=u)) into result;
 return result;
end$$;
revoke all on function public.mv_legend(text[]) from public,anon;
grant execute on function public.mv_legend(text[]) to authenticated;
revoke all on function mv_private.legend_complete(uuid,text),mv_private.legend_refresh(uuid,boolean) from public,anon,authenticated;
create function mv_private.legend_changed() returns trigger language plpgsql security definer set search_path='' as $$
begin
 perform mv_private.legend_refresh(new.family_id,false);return new;
end$$;
revoke all on function mv_private.legend_changed() from public,anon,authenticated;
create trigger legend_entry after insert or update on public.mv_entries for each row execute function mv_private.legend_changed();
create trigger legend_episode after insert or update on public.mv_episodes for each row execute function mv_private.legend_changed();
create trigger legend_rating after insert or update on public.mv_ratings for each row execute function mv_private.legend_changed();
do $$begin
 if exists(select 1 from pg_publication where pubname='supabase_realtime') then
 alter publication supabase_realtime add table public.mv_achievements;
 end if;
end$$;
